<script setup lang="ts">
import { ref, computed, onMounted, reactive } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api, headers, newKey } from '../api/client'
import { useAuth } from '../stores/auth'
import { money } from '../utils/format'
import RecordTable from '../components/RecordTable.vue'
const route=useRoute(), auth=useAuth(), section=computed(()=>String(route.params.section))
const titles:Record<string,string>={orders:'我的订单',wallet:'我的钱包',transactions:'资金流水',profile:'个人资料'}
const loading=ref(false),rows=ref<any[]>([]),total=ref(0),page=ref(1),status=ref(''),wallet=ref<any>({}),amount=ref(10000),busy=ref(false),events=ref<any[]>([]),eventsOpen=ref(false)
const name=ref(auth.user?.name || ''), passwords=reactive({current_password:'',new_password:''})
let rechargeKey=newKey(), rechargeAmount=amount.value
const orderColumns=[{key:'id',label:'订单编号',width:220},{key:'product_name',label:'商品',width:180},{key:'amount',label:'金额',type:'money'},{key:'payment_status',label:'支付状态',type:'status'},{key:'fulfillment_status',label:'履约状态',type:'status'},{key:'created_at',label:'创建时间',type:'date',width:180}]
const ledgerColumns=[{key:'id',label:'流水号'},{key:'kind',label:'类型',type:'status'},{key:'amount',label:'可用余额变动',type:'money'},{key:'frozen_delta',label:'冻结变动',type:'money'},{key:'balance_after',label:'变动后余额',type:'money'},{key:'note',label:'备注'},{key:'created_at',label:'时间',type:'date',width:180}]
async function load() { loading.value=true;try { if(section.value==='profile') {await auth.load();return;} if(section.value==='wallet') wallet.value=(await api.get('/me/wallet')).data; else { const {data}=await api.get(`/me/${section.value==='transactions'?'transactions':'orders'}`,{params:{page:page.value,status:status.value}});rows.value=data.items;total.value=data.total } }finally{loading.value=false} }
async function recharge(){busy.value=true;try{if(rechargeAmount!==amount.value){rechargeKey=newKey();rechargeAmount=amount.value}await api.post('/me/wallet/demo-recharge',{amount:amount.value},headers(rechargeKey));rechargeKey=newKey();ElMessage.success('演示充值成功');await load()}finally{busy.value=false}}
async function saveProfile(){busy.value=true;try{await api.patch('/auth/me',{name:name.value});await auth.load();ElMessage.success('资料已保存')}finally{busy.value=false}}
async function changePassword(){busy.value=true;try{await api.post('/auth/password',passwords);auth.clear();window.location.assign('/login')}finally{busy.value=false}}
async function sendVerification(){busy.value=true;try{const{data}=await api.post('/auth/verification/request');ElMessage.success(data.message)}finally{busy.value=false}}
async function showEvents(id:string){events.value=(await api.get(`/me/orders/${id}/events`)).data;eventsOpen.value=true}
onMounted(load)
</script>
<template><div class="section-heading"><div><p class="eyebrow">PERSONAL WORKSPACE</p><h1>{{ titles[section] || '用户中心' }}</h1></div><el-button @click="load" :loading="loading">刷新数据</el-button></div><template v-if="section==='wallet'"><div class="stats-grid"><div class="stat-card"><span>可用余额</span><strong>{{money(wallet.balance)}}</strong><small>用于购买平台数字服务</small></div><div class="stat-card"><span>冻结金额</span><strong>{{money(wallet.frozen)}}</strong><small>冻结金额暂不可用于消费</small></div></div><section class="panel"><h3>演示充值</h3><el-alert title="仅为测试资金，不涉及真实支付。生产环境必须关闭。" type="warning" :closable="false" /><form v-if="wallet.demo_recharge_enabled" @submit.prevent="recharge" class="inline-form"><label>充值金额（分）<el-input-number v-model="amount" :min="1" :max="1000000" :precision="0" /></label><el-button type="primary" native-type="submit" :loading="busy">充值 {{money(amount)}}</el-button></form><p v-else class="muted">演示充值已关闭</p><router-link to="/me/transactions">查看资金流水 →</router-link></section></template><template v-else-if="section==='profile'"><section class="panel form-panel"><h3>基本资料</h3><div class="email-verification-status"><el-tag :type="auth.user?.email_verified_at?'success':'info'">{{auth.user?.email_verified_at?'邮箱已验证':'邮箱未验证'}}</el-tag><el-button v-if="!auth.user?.email_verified_at && auth.features.email_verification_enabled" type="primary" plain :loading="busy" @click="sendVerification">发送验证邮件</el-button><p v-if="!auth.features.email_verification_enabled && !auth.user?.email_verified_at" class="muted">邮箱验证暂未开放。</p></div><form @submit.prevent="saveProfile"><label>登录邮箱<input :value="auth.user?.email" disabled /></label><label>昵称<input v-model="name" maxlength="80" /></label><el-button type="primary" native-type="submit" :loading="busy">保存资料</el-button></form></section><section class="panel form-panel"><h3>修改密码</h3><form @submit.prevent="changePassword"><label>原密码<input v-model="passwords.current_password" type="password" required autocomplete="current-password" /></label><label>新密码<input v-model="passwords.new_password" type="password" required minlength="10" maxlength="128" autocomplete="new-password" /></label><el-button type="primary" native-type="submit" :loading="busy">修改并重新登录</el-button></form></section></template><section v-else class="panel table-panel"><div v-if="section==='orders'" class="toolbar"><el-select v-model="status" placeholder="全部履约状态" clearable style="width:180px" @change="page=1;load()"><el-option v-for="(text,value) in {QUEUED:'待履约',COMPLETED:'已完成',FAILED:'失败',CANCELED:'已取消'}" :key="value" :value="value" :label="text" /></el-select></div><RecordTable :rows="rows" :columns="section==='orders'?orderColumns:ledgerColumns" :loading="loading"><el-table-column v-if="section==='orders'" label="记录" width="90"><template #default="{row}"><el-button link type="primary" @click="showEvents(row.id)">查看日志</el-button></template></el-table-column></RecordTable><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" /></section><el-dialog v-model="eventsOpen" title="订单处理记录" width="min(90vw,700px)"><RecordTable :rows="events" :columns="[{key:'action',label:'操作'},{key:'note',label:'说明'},{key:'created_at',label:'时间',type:'date',width:180}]" /></el-dialog></template>
